 async function analyze(text=input){
  if(!text.trim()||!state||!isActionCurrent())return;
  const scope=getAuthScope();setBusy(true);setUnknown([]);setPreviewDrafts({});
  try{
   if(aiReady&&online&&(user||anonymousAi)){
    if(user)await sync();if(!isActionCurrent())return;
    const terms=norm(text).split(/[^a-z0-9]+/).filter(x=>x.length>2);
    const foods=state.foods.filter(f=>terms.some(term=>norm(f.name+' '+f.brand+' '+f.aliases.join(' ')).includes(term))).slice(0,60);
    const result=await aiCall('analyze',{text,meal,date,foods},scope);if(!isActionCurrent())return;
    const items=(result.items as unknown[]).map(i=>itemSchema.parse(i));setPreview(items);setUnknown(result.unknown);setAnalyzeMode('ai');if(items[0]?.meal)setMeal(items[0].meal);
   }else{
    const result=parseLocal(text,allFoods,meal,date);setPreview(result.items);setUnknown(result.unknown);setAnalyzeMode('local');
   }
  }catch(e){if(isActionCurrent())toast.error((e as Error).message)}
  finally{if(isActionCurrent())setBusy(false)}
 }
 function savePreview(){
  if(!state||!preview.length||!isActionCurrent())return;
  if(!previewValid){toast.error('Provjeri količine prije spremanja.');return}
  const items=preview.map(i=>({...i,grams:parseQuantityDraft(previewDrafts[i.id]??String(i.grams))!,id:uid(),date,loggedAt:new Date().toISOString()}));
  try{
   const saved=update(s=>{
    const known=new Set([...baseFoods,...s.foods].map(f=>f.id)),cached:Food[]=[];
    if(scannedFood&&!known.has(scannedFood.id)){cached.push(scannedFood);known.add(scannedFood.id)}
    for(const item of items){
     if((item.source.startsWith('AI procjena')||item.source.startsWith('Web provjerena'))&&!known.has(item.foodId)){
      cached.push({id:item.foodId,name:item.name,brand:'',aliases:[searchAlias(item.name)],serving:item.grams,unit:item.unit,sourceUrls:item.sourceUrls,...item.basis,fiber:0,source:item.source,verified:false});known.add(item.foodId);
     }
    }
    return {...s,items:[...s.items,...items],foods:[...s.foods.map(f=>scannedFood?.id===f.id?scannedFood:f),...cached]};
   });if(!saved)return;
   const meals=[...new Set(items.map(i=>i.meal))];setOpenTodayMeal(meals[0]||null);toast.success(meals.length===1?`Dodano u ${t(meals[0]).toLowerCase()}`:'Obrok je dodan');setModal('');setPreview([]);setPreviewDrafts({});setScannedFood(null);
  }catch{toast.error('Obrok nije spremljen. Provjeri količine i dopuštena ograničenja.')}
 }
